"""Python 3.10+; only standard library. Submit once, resume by saved task ID."""
import argparse
import json
import mimetypes
import os
import time
import uuid
from pathlib import Path
from urllib.parse import quote, urljoin, urlsplit
from urllib.request import HTTPRedirectHandler, Request, build_opener


class NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, *args):
        return None


class Client:
    def __init__(self, base=None, key=None):
        self.base = (base or os.getenv("MEDIA_BASE_URL", "https://code.aicodeme.xyz")).rstrip("/")
        self.key = key or os.environ["MEDIA_API_KEY"]
        u = urlsplit(self.base)
        if u.scheme not in ("http", "https") or not u.netloc or u.path or u.query or u.fragment or u.username:
            raise ValueError("Base URL must be a site origin without /v1")
        if u.scheme == "http" and u.hostname not in ("localhost", "127.0.0.1", "::1"):
            raise ValueError("Use HTTPS")
        self.opener = build_opener(NoRedirect())

    def request(self, method, path, payload=None, extra=None):
        url = urljoin(self.base + "/", path)
        if urlsplit(url).netloc != urlsplit(self.base).netloc or urlsplit(url).scheme != urlsplit(self.base).scheme:
            raise ValueError("Artifact URL must belong to the API origin")
        headers = {"Authorization": "Bearer " + self.key, **(extra or {})}
        body = None
        if payload is not None:
            if isinstance(payload, bytes):
                body = payload
            else:
                body = json.dumps(payload, ensure_ascii=False).encode()
                headers["Content-Type"] = "application/json"
        return self.opener.open(Request(url, data=body, headers=headers, method=method), timeout=200)

    def json(self, method, path, payload=None, extra=None):
        with self.request(method, path, payload, extra) as r:
            return json.load(r)

    def download(self, artifact, directory, index):
        if not artifact.get("available", True):
            raise ValueError("Artifact unavailable")
        with self.request("GET", artifact["content_url"]) as r:
            mime = r.headers.get_content_type()
            extensions = {"image/png": ".png", "image/jpeg": ".jpg", "image/webp": ".webp", "video/mp4": ".mp4", "audio/mpeg": ".mp3", "audio/mp3": ".mp3", "audio/wav": ".wav", "audio/x-wav": ".wav", "audio/mp4": ".m4a", "audio/ogg": ".ogg", "audio/flac": ".flac", "application/octet-stream": ".bin"}
            if mime not in extensions:
                raise ValueError("Unexpected artifact MIME: " + mime)
            path = directory / (str(index) + extensions[mime])
            tmp = path.with_suffix(path.suffix + ".part")
            try:
                with tmp.open("wb") as f:
                    while chunk := r.read(65536):
                        f.write(chunk)
                tmp.replace(path)
            finally:
                tmp.unlink(missing_ok=True)
            return str(path)


def save(path, state, exclusive=False):
    if exclusive:
        with path.open("x", encoding="utf-8") as f:
            json.dump(state, f, ensure_ascii=False, indent=2)
    else:
        tmp = path.with_suffix(path.suffix + ".tmp")
        tmp.write_text(json.dumps(state, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(path)


def edit_body(payload, images):
    boundary = "media-" + uuid.uuid4().hex
    chunks = []
    for name, value in payload.items():
        value = value if isinstance(value, str) else json.dumps(value)
        chunks.append(f'--{boundary}\r\nContent-Disposition: form-data; name="{name}"\r\n\r\n{value}\r\n'.encode())
    for name in images:
        path = Path(name)
        mime = mimetypes.guess_type(path.name)[0]
        if mime not in ("image/png", "image/jpeg", "image/webp"):
            raise ValueError("Use PNG, JPEG or WebP references")
        chunks.extend([f'--{boundary}\r\nContent-Disposition: form-data; name="image[]"; filename="reference"\r\nContent-Type: {mime}\r\n\r\n'.encode(), path.read_bytes(), b"\r\n"])
    chunks.append(f"--{boundary}--\r\n".encode())
    return b"".join(chunks), "multipart/form-data; boundary=" + boundary


def submit(client, endpoint, payload, state_path, images=None):
    extra = {}
    if images:
        if endpoint != "/v1/images/edits" or len(images) > 2:
            raise ValueError("Image uploads require /v1/images/edits and 1-2 files")
        payload, extra["Content-Type"] = edit_body(payload, images)
    state = {"base": client.base, "idempotency_key": str(uuid.uuid4()), "task_id": None, "status": "submitting"}
    save(state_path, state, exclusive=True)
    # Never retry POST automatically, even if the connection times out.
    result = client.json("POST", endpoint, payload, {"Idempotency-Key": state["idempotency_key"], **extra})
    state.update(task_id=result.get("task_id") or result.get("id"), status=result.get("status", "submitted"))
    save(state_path, state)
    if not isinstance(state["task_id"], str) or not state["task_id"].strip():
        raise ValueError("Missing task ID; preserve state and reconcile, do not resubmit")
    return state


def resume(client, state_path, directory, interval=20, max_wait=3600):
    state = json.loads(state_path.read_text(encoding="utf-8"))
    if state["base"] != client.base or not state.get("task_id"):
        raise ValueError("State origin mismatch or no task ID; reconcile before another submission")
    deadline = time.monotonic() + max_wait
    path = "/v1/tasks/" + quote(state["task_id"], safe="")
    while time.monotonic() < deadline:
        task = client.json("GET", path)
        if task.get("id") != state["task_id"]:
            raise ValueError("Task ID mismatch")
        state["status"] = task["status"]
        save(state_path, state)
        if task["status"] == "completed":
            artifacts = client.json("GET", path + "/artifacts")["artifacts"]
            if not artifacts:
                raise ValueError("Completed task has no artifacts yet; retain ID and reconcile delivery")
            directory.mkdir(parents=True, exist_ok=True)
            files = [client.download(a, directory, i) for i, a in enumerate(artifacts)]
            state["files"] = files
            save(state_path, state)
            return files
        if task["status"] not in ("queued", "in_progress"):
            raise ValueError("Task " + task["status"] + "; retain ID for reconciliation")
        time.sleep(interval)
    raise TimeoutError("Polling ended; run resume again using the same state file")


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("command", choices=("submit", "resume"))
    p.add_argument("--endpoint", default="/v1/videos")
    p.add_argument("--payload", help="UTF-8 JSON file; required for submit")
    p.add_argument("--image", action="append", help="Local GPT edit reference; repeat for two files")
    p.add_argument("--state", default="media-task.json")
    p.add_argument("--output", default="media-output")
    p.add_argument("--interval", type=float, default=20)
    p.add_argument("--max-wait", type=float, default=3600)
    args = p.parse_args()
    if args.interval <= 0 or args.max_wait <= 0:
        p.error("interval and max-wait must be positive")
    client = Client()
    if args.command == "submit":
        if not args.payload:
            p.error("submit requires --payload")
        payload = json.loads(Path(args.payload).read_text(encoding="utf-8-sig"))
        print(submit(client, args.endpoint, payload, Path(args.state), args.image))
    else:
        print(resume(client, Path(args.state), Path(args.output), args.interval, args.max_wait))


if __name__ == "__main__":
    main()

// Node.js 20+. Server-side only: keep API keys out of browser bundles.
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises'
import { randomUUID } from 'node:crypto'
import { pathToFileURL } from 'node:url'
import { join, extname } from 'node:path'

export class Client {
  constructor(base = process.env.MEDIA_BASE_URL || 'https://code.aicodeme.xyz', key = process.env.MEDIA_API_KEY) {
    this.base = base.replace(/\/$/, '')
    this.key = key
    const u = new URL(this.base)
    if (!key || u.username || u.password || u.pathname !== '/' || u.search || u.hash || !['http:', 'https:'].includes(u.protocol)) throw new Error('Missing key or invalid site origin')
    if (u.protocol === 'http:' && !['localhost', '127.0.0.1', '[::1]'].includes(u.hostname)) throw new Error('Use HTTPS')
  }
  async request(method, path, payload, extra = {}) {
    const url = new URL(path, this.base + '/')
    if (url.origin !== this.base) throw new Error('Artifact URL must belong to the API origin')
    const headers = { Authorization: `Bearer ${this.key}`, ...extra }
    const multipart = payload instanceof FormData
    if (payload !== undefined && !multipart) headers['Content-Type'] = 'application/json'
    const r = await fetch(url, { method, headers, body: payload === undefined ? undefined : multipart ? payload : JSON.stringify(payload), redirect: 'error', signal: AbortSignal.timeout(200000) })
    if (!r.ok) throw new Error(`HTTP ${r.status}; retain task state; do not blindly resubmit`)
    return r
  }
  async json(...args) { return (await this.request(...args)).json() }
  async download(artifact, directory, index) {
    if (artifact.available === false) throw new Error('Artifact unavailable')
    const r = await this.request('GET', artifact.content_url)
    const mime = r.headers.get('content-type')?.split(';')[0].trim()
    const extensions = { 'image/png': '.png', 'image/jpeg': '.jpg', 'image/webp': '.webp', 'video/mp4': '.mp4', 'audio/mpeg': '.mp3', 'audio/mp3': '.mp3', 'audio/wav': '.wav', 'audio/x-wav': '.wav', 'audio/mp4': '.m4a', 'audio/ogg': '.ogg', 'audio/flac': '.flac', 'application/octet-stream': '.bin' }
    if (!extensions[mime]) throw new Error(`Unexpected artifact MIME: ${mime}`)
    const path = join(directory, `${index}${extensions[mime]}`)
    await writeFile(path, Buffer.from(await r.arrayBuffer()))
    return path
  }
}

async function save(path, state, exclusive = false) {
  if (exclusive) return writeFile(path, JSON.stringify(state, null, 2), { flag: 'wx' })
  await writeFile(path + '.tmp', JSON.stringify(state, null, 2))
  await rename(path + '.tmp', path)
}

export async function submit(client, endpoint, payload, statePath, images = []) {
  if (images.length) {
    if (endpoint !== '/v1/images/edits' || images.length > 2) throw new Error('Image uploads require /v1/images/edits and 1-2 files')
    const form = new FormData()
    for (const [name, value] of Object.entries(payload)) form.append(name, typeof value === 'string' ? value : JSON.stringify(value))
    for (const path of images) {
      const mime = { '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp' }[extname(path).toLowerCase()]
      if (!mime) throw new Error('Use PNG, JPEG or WebP references')
      form.append('image[]', new Blob([await readFile(path)], { type: mime }), 'reference' + extname(path))
    }
    payload = form
  }
  const state = { base: client.base, idempotency_key: randomUUID(), task_id: null, status: 'submitting' }
  await save(statePath, state, true)
  // Never automatically retry POST. State persists if the connection fails.
  const result = await client.json('POST', endpoint, payload, { 'Idempotency-Key': state.idempotency_key })
  state.task_id = result.task_id || result.id
  state.status = result.status || 'submitted'
  await save(statePath, state)
  if (typeof state.task_id !== 'string' || !state.task_id.trim()) throw new Error('Missing task ID; reconcile, do not resubmit')
  return state
}

export async function resume(client, statePath, directory, interval = 20, maxWait = 3600) {
  const state = JSON.parse(await readFile(statePath, 'utf8'))
  if (state.base !== client.base || !state.task_id) throw new Error('Origin mismatch or no task ID; reconcile')
  const deadline = Date.now() + maxWait * 1000
  const path = `/v1/tasks/${encodeURIComponent(state.task_id)}`
  while (Date.now() < deadline) {
    const task = await client.json('GET', path)
    if (task.id !== state.task_id) throw new Error('Task ID mismatch')
    state.status = task.status
    await save(statePath, state)
    if (task.status === 'completed') {
      const { artifacts } = await client.json('GET', path + '/artifacts')
      if (!artifacts.length) throw new Error('Completed task has no artifacts yet; retain ID and reconcile delivery')
      await mkdir(directory, { recursive: true })
      state.files = []
      for (const [i, artifact] of artifacts.entries()) state.files.push(await client.download(artifact, directory, i))
      await save(statePath, state)
      return state.files
    }
    if (!['queued', 'in_progress'].includes(task.status)) throw new Error(`Task ${task.status}; retain ID for reconciliation`)
    await new Promise(resolve => setTimeout(resolve, interval * 1000))
  }
  throw new Error('Polling ended; resume again using the same state file')
}

async function main() {
  const [command, ...rest] = process.argv.slice(2)
  const args = {}
  const images = []
  for (let i = 0; i < rest.length; i += 2) {
    const name = rest[i].replace(/^--/, '')
    if (name === 'image') images.push(rest[i + 1])
    else args[name] = rest[i + 1]
  }
  const client = new Client()
  const state = args.state || 'media-task.json'
  if (command === 'submit' && args.payload) {
    console.log(await submit(client, args.endpoint || '/v1/videos', JSON.parse((await readFile(args.payload, 'utf8')).replace(/^\uFEFF/, '')), state, images))
  } else if (command === 'resume') {
    const interval = Number(args.interval || 20), maxWait = Number(args['max-wait'] || 3600)
    if (!(interval > 0 && maxWait > 0)) throw new Error('interval and max-wait must be positive')
    console.log(await resume(client, state, args.output || 'media-output', interval, maxWait))
  } else throw new Error('Usage: node imagevideo.mjs submit --payload request.json --state task.json | resume --state task.json --output results')
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main().catch(e => { console.error(e.message); process.exitCode = 1 })
